#include <unistd.h>
#include <string.h>
#include <stdio.h>

void print_message(const char* message) {
    write(STDOUT_FILENO, message, strlen(message));
}

int main() {
    const char* test_msg = "Hello, World!";
    print_message(test_msg);
    return 0;
}
